// Plain-language definitions for database, operating-system and networking
// jargon. In those lessons, the first plain-text use of each term (outside code,
// links and headings) gets a dotted underline with this definition on hover or
// tap, linking to the lesson that explains it. A term applies only to lessons of
// its own subject (the subject of its `lesson`). A lesson that defines the term
// itself (its `lesson`, or any lesson where the term appears in bold) is left alone.
//
// Keep definitions short (≤ ~30 words) and free of other jargon where possible.
// Acronyms (all capitals) match case-sensitively; everything else ignores case.
// A trailing "s"/"es" is matched automatically.

export interface GlossaryEntry {
  term: string;
  aliases?: string[];
  def: string;
  lesson: string;
  /** Lesson ids (or id prefixes ending in "-") where the word usually means something else. */
  exclude?: string[];
  /** If set, only these lessons get the hover definition (for words with a common everyday sense). */
  only?: string[];
}

export const GLOSSARY: GlossaryEntry[] = [
  // ── Foundations and SQL ──
  { term: "primary key", def: "The column (or columns) chosen to identify each row: unique and never NULL.", lesson: "db-keys-constraints" },
  { term: "foreign key", def: "A column whose values must match a key in another table, so a row can't point at something that doesn't exist.", lesson: "db-keys-constraints" },
  { term: "candidate key", def: "A smallest set of columns that uniquely identifies every row. A table can have several; one becomes the primary key.", lesson: "db-keys-constraints" },
  { term: "surrogate key", def: "A meaningless generated identifier (an auto-increment number or a UUID) used as the key instead of real data like an email.", lesson: "db-keys-constraints" },
  { term: "NULL", def: "SQL's marker for an unknown or missing value. Comparing anything with it gives UNKNOWN, not true or false.", lesson: "sql-null-logic" },
  { term: "window function", def: "A calculation over a set of related rows (rank, running total, previous value) that keeps every row instead of collapsing them like GROUP BY.", lesson: "sql-window-functions" },
  { term: "CTE", aliases: ["common table expression"], def: "A named subquery written with WITH at the top of a query, so a complex query reads as a sequence of steps.", lesson: "sql-subqueries-ctes" },
  { term: "materialized view", def: "A stored copy of a query's result. Fast to read, but stale until it's refreshed.", lesson: "sql-views-programmability" },
  { term: "sargable", def: "Usable by an index: the column appears on its own in the condition, not wrapped in a function or arithmetic.", lesson: "sql-select-basics" },
  { term: "prepared statement", def: "A query sent once with placeholders, then executed many times with different values; the database parses (and may plan) it only once.", lesson: "db-query-lifecycle" },

  // ── Modeling ──
  { term: "functional dependency", aliases: ["functional dependencies"], def: "A rule X → Y: any two rows that agree on X must also agree on Y (an email determines a name).", lesson: "db-functional-dependencies" },
  { term: "normalization", def: "Organizing tables so each fact is stored exactly once, in the table whose key it describes.", lesson: "db-normalization" },
  { term: "denormalization", def: "Deliberately storing a fact in more than one place to make reads cheaper, at the cost of keeping the copies in sync.", lesson: "db-normalization" },

  // ── Storage and indexing ──
  { term: "page", exclude: ["sql-", "db-index-fundamentals", "db-redis-caching", "db-optimistic-pessimistic", "db-document-stores", "db-query-optimization", "db-partitioning"], def: "The fixed-size block (8 KB in PostgreSQL, 16 KB in InnoDB) that a database reads, caches and writes as one unit.", lesson: "db-pages-records" },
  { term: "tuple", def: "One stored row (or one version of a row). In relational theory, one fact in a table.", lesson: "db-pages-records" },
  { term: "heap", exclude: ["sql-", "db-scans-joins"], def: "A table stored as pages in no particular order; indexes point into it to find rows.", lesson: "db-pages-records" },
  { term: "TID", aliases: ["ctid"], def: "A row's physical address: (page number, slot number). PostgreSQL indexes store TIDs to find rows.", lesson: "db-pages-records" },
  { term: "buffer pool", def: "The database's own in-memory cache of disk pages. A page found there costs no disk read.", lesson: "db-buffer-pool" },
  { term: "B+ tree", def: "A shallow, balanced tree of pages: leaves hold keys in sorted order, upper levels route searches. A lookup reads one page per level.", lesson: "db-btree" },
  { term: "fanout", aliases: ["fan-out"], only: ["db-lsm-trees", "db-index-types-hashing", "db-composite-covering-indexes", "db-clustered-indexes", "db-pages-records", "db-index-fundamentals", "db-specialized-indexes"], def: "How many children each tree node has. Hundreds per page is what keeps a B+ tree only 3–4 levels deep.", lesson: "db-btree" },
  { term: "page split", def: "When a full B+ tree page is divided into two to make room for a new key.", lesson: "db-btree" },
  { term: "LSM tree", aliases: ["LSM"], def: "A storage structure that collects writes in memory and flushes them as sorted, never-modified files that are merged in the background.", lesson: "db-lsm-trees" },
  { term: "memtable", def: "The in-memory sorted buffer where an LSM tree collects recent writes before flushing them to a file.", lesson: "db-lsm-trees" },
  { term: "SSTable", def: "An immutable file of sorted key-value pairs written by an LSM tree.", lesson: "db-lsm-trees" },
  { term: "compaction", def: "Merging LSM files into new ones, dropping overwritten and deleted values.", lesson: "db-lsm-trees" },
  { term: "tombstone", def: "A marker recording that a key was deleted, so older copies of the value elsewhere are ignored until cleanup.", lesson: "db-lsm-trees" },
  { term: "Bloom filter", def: "A tiny summary of a file's keys that can answer \"definitely not here\" without reading the file (with a small chance of a false \"maybe\").", lesson: "db-lsm-trees" },
  { term: "column store", aliases: ["columnar"], def: "A database that stores each column separately, so analytical queries read only the columns they use.", lesson: "db-column-stores" },
  { term: "OLTP", def: "Online transaction processing: many short transactions that read or change a few rows by key (orders, payments).", lesson: "db-column-stores" },
  { term: "OLAP", def: "Online analytical processing: few, large queries that scan and aggregate many rows (reports, dashboards).", lesson: "db-column-stores" },
  { term: "secondary index", def: "An index stored separately from the table, whose entries point back to rows by address or by primary key.", lesson: "db-index-fundamentals" },
  { term: "selectivity", def: "The fraction of rows a condition matches. A small fraction means an index is worth using.", lesson: "db-index-fundamentals" },
  { term: "composite index", aliases: ["multi-column index"], def: "An index on several columns, sorted by the first, then by the second within each first value, and so on.", lesson: "db-composite-covering-indexes" },
  { term: "covering index", def: "An index that contains every column a query needs, so the table itself never has to be read.", lesson: "db-composite-covering-indexes" },
  { term: "index-only scan", def: "A plan that answers a query from index pages alone, without visiting the table.", lesson: "db-composite-covering-indexes" },
  { term: "clustered index", def: "An index whose leaves contain the table's rows, so the table itself is stored in key order (InnoDB's primary key).", lesson: "db-clustered-indexes" },
  { term: "partial index", def: "An index containing only the rows that match a condition, such as status = 'pending'.", lesson: "db-specialized-indexes" },
  { term: "GIN", def: "PostgreSQL's inverted index: maps each word, JSON key or array element to the rows containing it.", lesson: "db-specialized-indexes" },
  { term: "BRIN", def: "A tiny PostgreSQL index storing min and max values per block range; useful when data is physically in order, like append-only time data.", lesson: "db-specialized-indexes" },

  // ── Query execution ──
  { term: "query planner", aliases: ["planner", "query optimizer"], def: "The part of the database that decides how to run a query, by estimating the cost of alternative plans and picking the cheapest.", lesson: "db-query-lifecycle" },
  { term: "sequential scan", aliases: ["seq scan", "full table scan"], def: "Reading every page of a table in order, checking each row.", lesson: "db-scans-joins" },
  { term: "bitmap scan", aliases: ["bitmap heap scan", "bitmap index scan"], def: "Collect matching row addresses from an index, sort them by page, then read each needed page once.", lesson: "db-scans-joins" },
  { term: "nested loop", aliases: ["nested-loop join"], def: "A join that, for each row on one side, looks up matching rows on the other; fast when that lookup uses an index.", lesson: "db-scans-joins" },
  { term: "hash join", def: "A join that builds a hash table on the smaller input, then probes it once for each row of the larger input.", lesson: "db-scans-joins" },
  { term: "merge join", def: "A join that walks two inputs sorted on the join key side by side, like merging two sorted lists.", lesson: "db-scans-joins" },
  { term: "EXPLAIN", def: "Shows the plan the database chose for a query. EXPLAIN ANALYZE also runs it and reports actual row counts and times.", lesson: "db-explain" },

  // ── Transactions and concurrency ──
  { term: "transaction", exclude: ["sql-window-functions"], def: "A group of statements the database treats as one step: all or nothing, isolated from others, and permanent once committed.", lesson: "db-transactions-acid" },
  { term: "ACID", def: "Atomicity, consistency, isolation, durability: the four promises a transaction makes.", lesson: "db-transactions-acid" },
  { term: "WAL", aliases: ["write-ahead log"], def: "Write-ahead log: an append-only record of every change, flushed to disk at commit before the data pages are written. Replaying it recovers from crashes.", lesson: "db-wal-durability" },
  { term: "LSN", def: "Log sequence number: a record's position in the WAL. Each page remembers the LSN of the last change applied to it.", lesson: "db-wal-durability" },
  { term: "checkpoint", def: "A point after which all earlier changes are on disk, so crash recovery can start replaying the log from there.", lesson: "db-wal-durability" },
  { term: "fsync", def: "The system call that forces a file's buffered writes onto stable storage. Until it returns, \"written\" data may still be only in memory.", lesson: "db-wal-durability" },
  { term: "dirty read", def: "Reading another transaction's change before it has committed (it might still be rolled back).", lesson: "db-anomalies" },
  { term: "non-repeatable read", def: "Reading the same row twice in one transaction and getting different values, because someone committed a change in between.", lesson: "db-anomalies" },
  { term: "phantom", aliases: ["phantom read"], exclude: ["db-distributed-transactions"], def: "A row that appears or disappears when a transaction repeats a range query, because another transaction inserted or deleted it.", lesson: "db-anomalies" },
  { term: "lost update", def: "Two transactions read the same value and both write back a new one, so one of the changes silently disappears.", lesson: "db-anomalies" },
  { term: "write skew", def: "Two transactions each check a rule, then update different rows. Each was fine alone; together they break the rule.", lesson: "db-anomalies" },
  { term: "precedence graph", def: "A graph with an edge Ti → Tj for each pair of conflicting operations where Ti's came first. A cycle means no equivalent serial order exists.", lesson: "db-schedules-serializability" },
  { term: "serializable", aliases: ["serializability"], def: "The strongest isolation guarantee: the result equals running the transactions one at a time, in some order.", lesson: "db-schedules-serializability" },
  { term: "isolation level", def: "How much concurrently running transactions can see of each other's changes: Read Committed, Repeatable Read or Serializable.", lesson: "db-isolation-levels" },
  { term: "Read Committed", def: "Isolation level where each statement sees only data committed before that statement started.", lesson: "db-isolation-levels" },
  { term: "Repeatable Read", def: "Isolation level where the whole transaction reads one snapshot (PostgreSQL); MySQL also locks ranges for locking reads.", lesson: "db-isolation-levels" },
  { term: "snapshot isolation", def: "Each transaction reads one consistent snapshot and fails if it updates a row someone else changed meanwhile. Still allows write skew.", lesson: "db-isolation-levels" },
  { term: "shared lock", def: "A lock many transactions can hold at once, typically for reading; it blocks exclusive locks.", lesson: "db-locking" },
  { term: "exclusive lock", def: "A lock only one transaction can hold, typically for writing; it blocks every other lock on the same item.", lesson: "db-locking" },
  { term: "deadlock", def: "Two or more transactions each waiting for a lock another one holds. The database breaks the cycle by aborting one.", lesson: "db-locking" },
  { term: "gap lock", aliases: ["next-key lock"], def: "InnoDB's lock on the space between index entries, stopping inserts into a range another transaction is reading.", lesson: "db-locking" },
  { term: "two-phase locking", aliases: ["2PL", "strict 2PL"], def: "Take locks as you need them and release none until you have them all (in practice, hold them until commit). Guarantees serializability.", lesson: "db-concurrency-protocols" },
  { term: "MVCC", def: "Multi-version concurrency control: updates create new row versions, and each transaction reads the versions matching its snapshot, so readers and writers don't block each other.", lesson: "db-mvcc" },
  { term: "snapshot", exclude: ["db-backups-pitr", "db-data-warehousing", "db-failover", "db-normalization", "db-schema-design", "db-crash-recovery", "db-sharding", "db-redis-caching", "db-document-stores", "db-security"], def: "The set of committed changes a transaction (or statement) is allowed to see, fixed when it starts.", lesson: "db-mvcc" },
  { term: "xmin", aliases: ["xmax"], def: "Transaction ids stamped on a PostgreSQL row version: xmin created it, xmax deleted or replaced it.", lesson: "db-mvcc" },
  { term: "VACUUM", aliases: ["autovacuum"], def: "PostgreSQL's cleanup that removes row versions no transaction can see any more and makes their space reusable.", lesson: "db-mvcc" },
  { term: "HOT update", def: "Heap-only tuple update in PostgreSQL: the new row version stays on the same page, so no index entries are added.", lesson: "db-mvcc" },
  { term: "undo log", def: "Where InnoDB keeps old row versions, used to roll back and to show older snapshots to readers.", lesson: "db-mvcc" },
  { term: "optimistic concurrency control", aliases: ["optimistic locking", "OCC"], def: "Work without locks, then check at write time that nothing you read has changed; retry if it has.", lesson: "db-optimistic-pessimistic" },
  { term: "idempotent", aliases: ["idempotency"], def: "Safe to repeat: doing it twice has the same effect as doing it once.", lesson: "db-optimistic-pessimistic" },
  { term: "ARIES", def: "The classic crash-recovery algorithm: analyse the log, redo every change, then undo transactions that never committed.", lesson: "db-crash-recovery" },
  { term: "PITR", aliases: ["point-in-time recovery"], def: "Point-in-time recovery: restore a backup, then replay the log up to a chosen moment, such as just before a bad DELETE.", lesson: "db-backups-pitr" },
  { term: "RPO", def: "Recovery point objective: how much recent data you can afford to lose, measured in time.", lesson: "db-backups-pitr" },
  { term: "RTO", def: "Recovery time objective: how long recovery is allowed to take before service is back.", lesson: "db-backups-pitr" },

  // ── Distributed ──
  { term: "replica", aliases: ["follower", "standby", "read replica"], def: "A copy of the database that applies the primary's changes in the same order; it may serve reads.", lesson: "db-replication" },
  { term: "replication lag", def: "How far a replica is behind the primary, in bytes of log or seconds. Reads from a lagging replica can be stale.", lesson: "db-replication" },
  { term: "failover", def: "Promoting a replica to be the new primary after the primary fails.", lesson: "db-failover" },
  { term: "split brain", def: "Two nodes both acting as primary and accepting different writes, so the data's history forks.", lesson: "db-failover" },
  { term: "fencing", def: "Making sure an old primary can no longer accept writes: power it off, revoke its lease, or reject its requests.", lesson: "db-failover" },
  { term: "partition pruning", def: "Skipping the partitions of a table that can't contain matching rows.", lesson: "db-partitioning" },
  { term: "shard", aliases: ["sharding"], def: "One of several independent databases that each hold a slice of the data, chosen by a key.", lesson: "db-sharding" },
  { term: "shard key", def: "The column that decides which shard a row lives on, such as tenant_id or user_id.", lesson: "db-sharding" },
  { term: "consistent hashing", def: "Placing servers and keys on a hash ring, so adding or removing a server moves only about 1/N of the keys.", lesson: "db-consistent-hashing" },
  { term: "virtual nodes", aliases: ["vnodes"], def: "Placing each server at many points on a hash ring, which evens out how much data each one owns.", lesson: "db-consistent-hashing" },
  { term: "quorum", def: "Enough replicas (often a majority) that any two such groups share at least one member.", lesson: "db-quorums-consensus" },
  { term: "consensus", def: "Getting several nodes to agree on one sequence of decisions even when some crash (Raft, Paxos).", lesson: "db-quorums-consensus" },
  { term: "Raft", def: "A consensus algorithm: an elected leader appends commands to a log and a command counts once a majority has stored it.", lesson: "db-quorums-consensus" },
  { term: "linearizability", aliases: ["linearizable"], def: "Every operation appears to happen instantly at one point in time, so a read always sees the latest completed write — as if there were one copy.", lesson: "db-consistency-models" },
  { term: "eventual consistency", aliases: ["eventually consistent"], def: "If writes stop, all replicas eventually agree; until then, reads may return old values.", lesson: "db-consistency-models" },
  { term: "read-your-writes", def: "A guarantee that you always see your own earlier writes, even when reading from replicas.", lesson: "db-consistency-models" },
  { term: "CAP theorem", aliases: ["CAP"], def: "When the network splits replicas apart, each request must either wait/fail (consistency) or answer from local data (availability).", lesson: "db-cap-pacelc" },
  { term: "two-phase commit", aliases: ["2PC"], def: "Ask every participant to prepare, then send all of them the same commit-or-abort decision.", lesson: "db-distributed-transactions" },
  { term: "saga", def: "A sequence of local transactions, each with a compensating action that undoes it if a later step fails.", lesson: "db-distributed-transactions" },
  { term: "transactional outbox", aliases: ["outbox"], def: "Write the data change and the event to publish in one local transaction; a relay sends the event afterwards, so neither can happen without the other.", lesson: "db-distributed-transactions" },

  // ── In practice ──
  { term: "SQL injection", def: "An attack where input pasted into SQL text changes what the query does. Prevented with parameterized queries.", lesson: "db-security" },
  { term: "row-level security", aliases: ["RLS"], def: "Database policies that filter which rows each session can see or change, for example one tenant's rows.", lesson: "db-security" },
  { term: "star schema", def: "A warehouse layout: one large fact table of measurements joined to small descriptive dimension tables.", lesson: "db-data-warehousing" },
  { term: "fact table", def: "A warehouse table with one row per measured event (a sale, a click), holding the numbers and keys to its dimensions.", lesson: "db-data-warehousing" },
  { term: "dimension table", def: "A warehouse table of descriptive attributes (product, customer, date) used to filter and group the facts.", lesson: "db-data-warehousing" },
  { term: "CDC", aliases: ["change data capture"], def: "Change data capture: streaming every insert, update and delete out of a database, usually by reading its log.", lesson: "db-data-warehousing" },

  // ══════════════════ Operating systems ══════════════════

  // ── Foundations ──
  { term: "kernel", def: "The core of the OS, running with full hardware privilege: it schedules programs, manages memory and talks to devices for them.", lesson: "os-what-an-os-does" },
  { term: "user mode", aliases: ["user space"], def: "The CPU's restricted mode where applications run: no privileged instructions, and memory limited to the process's own pages.", lesson: "os-what-an-os-does" },
  { term: "kernel mode", def: "The CPU's privileged mode, used only by kernel code: every instruction and all of memory are allowed.", lesson: "os-what-an-os-does" },
  { term: "system call", aliases: ["syscall"], def: "A request from a program to the kernel (read a file, open a socket), made with a special instruction that switches the CPU into kernel mode.", lesson: "os-syscalls-interrupts" },
  { term: "interrupt", def: "A hardware signal from a device or the timer that makes the CPU pause what it's doing and run a kernel handler.", lesson: "os-syscalls-interrupts", exclude: ["os-signals", "os-threads", "os-atomic-instructions"] },
  { term: "vDSO", def: "A tiny library the kernel maps into every process, so calls like clock_gettime run without entering the kernel.", lesson: "os-syscalls-interrupts" },
  { term: "DMA", def: "Direct memory access: a device copies data to or from RAM by itself and interrupts the CPU only when the transfer is done.", lesson: "os-hardware-model" },
  { term: "cache line", def: "The 64-byte chunk in which data moves between RAM and the CPU caches. Reading one byte loads its whole line.", lesson: "os-hardware-model" },
  { term: "locality", def: "Programs tend to reuse recently used data (temporal) and data next to it (spatial). It's why caches work.", lesson: "os-hardware-model" },
  { term: "ELF", def: "The Linux executable file format: its headers tell the loader which parts to map as code and data and where to start.", lesson: "os-program-execution" },
  { term: "dynamic linking", def: "Loading shared libraries such as libc when a program starts, instead of copying them into every executable.", lesson: "os-program-execution" },
  { term: "JIT compiler", aliases: ["JIT"], def: "The part of the JVM that compiles frequently run bytecode into machine code while the program runs.", lesson: "os-program-execution" },

  // ── Processes ──
  { term: "process", def: "A running program: its own address space, open files and at least one thread, tracked by the kernel.", lesson: "os-processes", exclude: ["os-concurrency-vs-parallelism", "os-hugepages-numa"] },
  { term: "PCB", aliases: ["process control block"], def: "The kernel's record for a process: state, saved registers, memory map, open files, scheduling data and credentials.", lesson: "os-processes" },
  { term: "PID", def: "Process ID: the number the kernel uses to identify a process.", lesson: "os-processes" },
  { term: "fork", def: "The Unix call that creates a child process as a near-copy of its parent; both continue from the same point.", lesson: "os-process-creation", exclude: ["os-classic-sync-problems"] },
  { term: "zombie", def: "A process that has exited but whose parent hasn't collected its exit status; it still holds a PID.", lesson: "os-process-creation" },
  { term: "orphan", def: "A process whose parent exited first. The kernel re-parents it to PID 1, which will clean it up.", lesson: "os-process-creation" },
  { term: "signal", def: "A small numbered notification the kernel delivers to a process (Ctrl+C, a child exited, please stop); it can be handled, ignored, or kill the process.", lesson: "os-signals", only: ["os-process-creation", "os-processes", "os-ipc", "os-what-an-os-does", "os-virtualization-containers", "os-program-execution"] },
  { term: "SIGTERM", def: "The polite termination signal: the process may catch it, clean up and exit. Orchestrators send it first.", lesson: "os-signals" },
  { term: "SIGKILL", def: "The signal that can't be caught or ignored: the kernel ends the process at once, with no cleanup.", lesson: "os-signals" },
  { term: "context switch", def: "The kernel saving one thread's CPU state and restoring another's, so a different thread runs on that core.", lesson: "os-context-switch" },
  { term: "IPC", def: "Inter-process communication: ways for separate processes to exchange data, such as pipes, sockets and shared memory.", lesson: "os-ipc", exclude: ["os-hardware-model", "os-cpu-caches-contention"] },
  { term: "pipe", def: "A one-way kernel buffer between processes: one writes bytes in, the other reads them out.", lesson: "os-ipc", exclude: ["os-what-an-os-does"] },
  { term: "shared memory", def: "Physical memory mapped into several processes at once, so they exchange data without copying it through the kernel.", lesson: "os-ipc", exclude: ["os-hugepages-numa"] },

  // ── Threads and synchronization ──
  { term: "thread", def: "One flow of execution inside a process: its own registers and stack, sharing the process's memory and files.", lesson: "os-threads" },
  { term: "virtual thread", def: "A Java thread scheduled by the JVM rather than the kernel. Many share a few kernel threads, and blocking parks one cheaply.", lesson: "os-threads" },
  { term: "thread pool", def: "A fixed set of reusable worker threads taking tasks from a queue, which bounds concurrency and avoids creating threads per task.", lesson: "os-thread-pools" },
  { term: "backpressure", def: "Slowing a producer down when the consumer can't keep up, instead of buffering without limit.", lesson: "os-thread-pools" },
  { term: "race condition", def: "A bug where the result depends on thread timing you don't control, such as two threads updating one counter at once.", lesson: "os-race-conditions" },
  { term: "data race", def: "Two threads accessing the same memory at once, at least one writing, with nothing ordering them.", lesson: "os-race-conditions" },
  { term: "happens-before", def: "The memory-model rule that guarantees one thread sees another's writes, such as an unlock before a later lock of the same lock.", lesson: "os-race-conditions" },
  { term: "memory barrier", def: "An instruction that stops the CPU and compiler from moving memory reads and writes across it.", lesson: "os-race-conditions" },
  { term: "critical section", def: "Code that touches shared data and must not run in two threads at the same time.", lesson: "os-critical-section-problem" },
  { term: "busy waiting", aliases: ["busy-waiting"], def: "Waiting by looping and re-checking a condition, which keeps a CPU busy instead of sleeping.", lesson: "os-critical-section-problem" },
  { term: "mutex", def: "A lock with an owner: one thread holds it at a time, and the others wait until it is released.", lesson: "os-sync-primitives" },
  { term: "spinlock", def: "A lock whose waiters keep checking it in a loop instead of sleeping. Good only when it's held very briefly.", lesson: "os-sync-primitives" },
  { term: "condition variable", def: "A place where a thread sleeps, holding no lock, until another thread signals that shared data may have changed. Always used with a lock.", lesson: "os-sync-primitives" },
  { term: "futex", def: "The Linux primitive under most locks: an uncontended lock or unlock is one atomic instruction, and the kernel is called only to sleep or wake.", lesson: "os-sync-primitives" },
  { term: "priority inversion", def: "A high-priority task waits for a lock held by a low-priority task, which is itself held up by medium-priority work.", lesson: "os-sync-primitives" },
  { term: "semaphore", def: "A counter threads can wait on: acquiring takes a permit (waiting at zero), releasing returns one.", lesson: "os-semaphores-monitors" },
  { term: "monitor", def: "An object whose methods run one thread at a time, with condition variables for waiting, as in Java's synchronized with wait and notify.", lesson: "os-semaphores-monitors", only: ["os-sync-primitives", "os-classic-sync-problems", "os-race-conditions", "os-critical-section-problem", "os-atomic-instructions", "os-deadlocks", "os-threads"] },
  { term: "atomic instruction", aliases: ["atomic operation"], def: "A CPU instruction that reads and writes memory as one indivisible step, such as compare-and-swap or fetch-and-add.", lesson: "os-atomic-instructions" },
  { term: "compare-and-swap", aliases: ["CAS"], def: "An atomic instruction: change a value from A to B only if it still holds A; otherwise report failure. The basis of lock-free code.", lesson: "os-atomic-instructions" },
  { term: "deadlock", def: "Threads each holding something and waiting for something another one holds, in a cycle, so none can ever continue.", lesson: "os-deadlocks" },
  { term: "livelock", def: "Threads keep acting, such as retrying and backing off, but never make progress.", lesson: "os-deadlocks" },
  { term: "Coffman conditions", def: "The four conditions a deadlock needs at once: mutual exclusion, hold and wait, no preemption, and circular wait.", lesson: "os-deadlocks" },
  { term: "safe state", def: "A state in which some order exists that lets every process get its maximum needs and finish, so deadlock can still be avoided.", lesson: "os-deadlock-handling" },
  { term: "Banker's algorithm", def: "Deadlock avoidance that grants a request only if the system stays in a safe state afterwards.", lesson: "os-deadlock-handling" },

  // ── Scheduling ──
  { term: "scheduler", def: "The kernel code that decides which ready thread runs next on each CPU, and for how long.", lesson: "os-scheduling-basics", exclude: ["os-what-an-os-does", "os-storage-devices", "os-cpu-caches-contention"] },
  { term: "preemption", aliases: ["preemptive"], def: "Taking the CPU away from a running thread, usually when its time slice ends or a more urgent thread wakes up.", lesson: "os-scheduling-basics" },
  { term: "time slice", aliases: ["quantum"], def: "How long a thread may run before the scheduler can switch to another, typically a few milliseconds.", lesson: "os-scheduling-basics" },
  { term: "turnaround time", def: "Completion time minus arrival time: how long a job spends in the system in total.", lesson: "os-scheduling-basics" },
  { term: "convoy effect", def: "Short jobs stuck behind one long job, as happens with first-come-first-served scheduling.", lesson: "os-scheduling-basics" },
  { term: "starvation", def: "A process waits indefinitely because others are always chosen ahead of it.", lesson: "os-scheduling-algorithms" },
  { term: "aging", def: "Raising a job's priority the longer it waits, so it can't starve.", lesson: "os-scheduling-algorithms" },
  { term: "MLFQ", def: "Multilevel feedback queue: new jobs start at top priority and drop a level each time they use a full time slice.", lesson: "os-mlfq-real-schedulers" },
  { term: "CFS", aliases: ["EEVDF"], def: "Linux's fair scheduler: it runs the task that has had the least CPU time relative to its weight.", lesson: "os-mlfq-real-schedulers" },
  { term: "load average", def: "Linux's moving average of tasks that are runnable or in uninterruptible sleep. It is not CPU usage.", lesson: "os-performance-method" },

  // ── Memory ──
  { term: "virtual memory", def: "Each process gets its own private address space, translated by hardware to physical RAM, so processes are isolated and can map more than fits.", lesson: "os-address-spaces" },
  { term: "address space", def: "The range of memory addresses a process can use. Each process has its own.", lesson: "os-address-spaces" },
  { term: "ASLR", def: "Address space layout randomization: placing the stack, heap and libraries at random addresses each run, to make exploits harder.", lesson: "os-address-spaces" },
  { term: "internal fragmentation", def: "Space wasted inside allocated blocks, because requests are rounded up to a block or size class.", lesson: "os-dynamic-allocation" },
  { term: "external fragmentation", def: "Free memory split into holes that are each too small for a request, though together they would be enough.", lesson: "os-dynamic-allocation" },
  { term: "garbage collector", aliases: ["garbage collection", "GC"], def: "The runtime part that finds objects nothing refers to any more and reclaims their memory automatically.", lesson: "os-dynamic-allocation", exclude: ["os-hardware-model", "os-storage-devices"] },
  { term: "MMU", def: "The CPU unit that translates each virtual address to a physical one using the page tables, checking permissions as it goes.", lesson: "os-paging" },
  { term: "page", def: "A fixed-size block of virtual memory, usually 4 KB: the unit the OS maps, loads and evicts.", lesson: "os-paging", exclude: ["os-storage-devices", "os-sync-primitives", "os-atomic-instructions", "os-filesystem-internals", "os-hugepages-numa", "os-profiling-observability", "os-performance-method"] },
  { term: "frame", def: "A page-sized block of physical RAM that holds one page.", lesson: "os-paging", only: ["os-tlb", "os-page-faults", "os-page-replacement", "os-thrashing-working-set", "os-segmentation", "os-hugepages-numa", "os-cow-mmap", "os-dynamic-allocation"] },
  { term: "page table", def: "The per-process map the MMU uses to translate virtual pages to physical frames, with permission bits for each page.", lesson: "os-paging" },
  { term: "TLB", def: "Translation lookaside buffer: a small CPU cache of recent virtual-to-physical page translations.", lesson: "os-tlb" },
  { term: "page fault", def: "The CPU trapping into the kernel because a page isn't mapped or doesn't allow the access. Usually the kernel just loads or maps it.", lesson: "os-page-faults" },
  { term: "demand paging", def: "Loading a page into RAM only when the program first touches it, rather than loading everything up front.", lesson: "os-page-faults" },
  { term: "working set", def: "The pages a process has used recently: an estimate of how much memory it needs right now.", lesson: "os-thrashing-working-set", exclude: ["os-hardware-model"] },
  { term: "thrashing", def: "So much paging that the machine spends its time moving pages to and from disk instead of doing work.", lesson: "os-thrashing-working-set", exclude: ["os-mlfq-real-schedulers"] },
  { term: "swap", aliases: ["swapping"], def: "Disk space where the kernel puts memory pages it needs to free. Reading them back is slow.", lesson: "os-thrashing-working-set", exclude: ["os-journaling", "os-scheduling-algorithms", "os-atomic-instructions", "os-critical-section-problem", "os-process-creation", "os-race-conditions", "os-sync-primitives", "os-dynamic-allocation", "os-java-memory-model"] },
  { term: "OOM killer", def: "The kernel mechanism that kills a process, chosen mostly by memory size, when memory can't be freed any other way.", lesson: "os-thrashing-working-set" },
  { term: "copy-on-write", aliases: ["COW"], def: "Sharing pages read-only and copying a page only when someone writes to it. It makes fork and snapshots cheap.", lesson: "os-cow-mmap", exclude: ["os-java-memory-model"] },
  { term: "mmap", def: "The call that maps a file (or anonymous memory) into a process's address space, so it can be used like ordinary memory.", lesson: "os-cow-mmap" },
  { term: "huge page", def: "A 2 MB or 1 GB page instead of 4 KB, so one TLB entry covers far more memory.", lesson: "os-hugepages-numa" },
  { term: "NUMA", def: "A multi-socket design where each CPU socket has its own RAM; memory attached to another socket is slower to reach.", lesson: "os-hugepages-numa" },

  // ── Storage and files ──
  { term: "SSD", def: "A solid-state drive: flash memory with no moving parts. Fast random reads, but flash must be erased before it is rewritten.", lesson: "os-storage-devices" },
  { term: "NVMe", def: "The interface for SSDs attached over PCIe, with many deep command queues for parallel I/O.", lesson: "os-storage-devices" },
  { term: "IOPS", def: "I/O operations per second: how many separate reads or writes a storage device completes each second.", lesson: "os-storage-devices" },
  { term: "FTL", def: "Flash translation layer: SSD firmware that maps logical blocks to flash pages, spreads wear and collects garbage.", lesson: "os-storage-devices" },
  { term: "write amplification", def: "A device writing more data to flash than the host asked for, because garbage collection moves still-valid data.", lesson: "os-storage-devices" },
  { term: "seek time", def: "How long a hard disk's arm takes to move to the right track: milliseconds for every random access.", lesson: "os-storage-devices" },
  { term: "file descriptor", aliases: ["fd"], def: "A small integer a process uses to refer to an open file, socket or pipe: an index into its table of open files.", lesson: "os-file-descriptors" },
  { term: "inode", def: "The on-disk record describing a file (owner, permissions, size, where its blocks are): everything except its name.", lesson: "os-filesystem-internals" },
  { term: "hard link", def: "A second directory entry for the same inode: another name for the same file.", lesson: "os-filesystem-internals" },
  { term: "symbolic link", aliases: ["symlink"], def: "A small file containing the path of another file. It breaks if the target is moved or deleted.", lesson: "os-filesystem-internals" },
  { term: "fsync", def: "The call that makes a file's written data durable: it returns only once the data has reached stable storage.", lesson: "os-journaling" },
  { term: "journaling", def: "Recording a change in a log before applying it to the real structures, so a crash can be recovered quickly.", lesson: "os-journaling" },
  { term: "page cache", def: "Kernel memory holding recently used file contents, so reads can skip the disk and writes can be batched.", lesson: "os-page-cache" },
  { term: "dirty page", def: "A cached page that was changed in memory but not yet written back to disk.", lesson: "os-page-cache" },
  { term: "writeback", def: "The kernel flushing dirty pages to disk in the background.", lesson: "os-page-cache" },
  { term: "read-ahead", def: "The kernel reading the next parts of a file before they're requested, when access looks sequential.", lesson: "os-page-cache" },
  { term: "RAID", def: "Combining several disks into one for speed (striping), safety (mirroring or parity), or both.", lesson: "os-raid" },

  // ── I/O, performance and isolation ──
  { term: "non-blocking I/O", def: "I/O calls that return at once if they can't proceed, so one thread can serve many connections.", lesson: "os-io-models" },
  { term: "io_uring", def: "Linux's asynchronous I/O interface: requests and results pass through rings shared with the kernel, with few system calls.", lesson: "os-io-models" },
  { term: "epoll", def: "Linux's scalable way to wait on many sockets at once: it returns only the ones that are ready.", lesson: "os-epoll-event-loops" },
  { term: "event loop", def: "One thread that repeatedly waits for ready connections and runs a short handler for each. It must never block.", lesson: "os-epoll-event-loops" },
  { term: "Little's Law", def: "Items in a system = arrival rate × time each spends there (L = λW). Used to size pools and concurrency.", lesson: "os-performance-method" },
  { term: "false sharing", def: "Threads writing different variables that sit on the same cache line, so the line bounces between cores.", lesson: "os-cpu-caches-contention" },
  { term: "flame graph", def: "A picture of profiler samples: each box is a function, and its width shows how often it was on the stack.", lesson: "os-profiling-observability" },
  { term: "eBPF", def: "A way to run small, verified programs inside the Linux kernel to trace and measure events cheaply.", lesson: "os-profiling-observability" },
  { term: "cgroup", def: "A Linux control group: it limits and accounts the CPU, memory and I/O a group of processes may use. Containers are built on cgroups.", lesson: "os-virtualization-containers" },
  { term: "namespace", def: "A Linux feature giving processes their own view of something global, such as process IDs, network interfaces or mounts.", lesson: "os-virtualization-containers" },
  { term: "container", def: "A process isolated with namespaces and limited with cgroups, sharing the host's kernel.", lesson: "os-virtualization-containers", exclude: ["os-program-execution"] },
  { term: "hypervisor", def: "Software that runs virtual machines, giving each its own virtual CPUs, memory and devices.", lesson: "os-virtualization-containers" },

  // ── The JVM and security ──
  { term: "safepoint", def: "A moment when every Java thread is stopped at a known point, so the JVM can safely do work such as some garbage-collection phases.", lesson: "os-jvm-on-linux" },
  { term: "RSS", aliases: ["resident set size"], def: "The part of a process's memory actually in RAM right now. Container memory limits and the OOM killer act on it.", lesson: "os-jvm-on-linux", exclude: ["os-syscalls-interrupts", "os-hardware-model"] },
  { term: "setuid", def: "A permission bit that makes a program run with its file owner's user ID (often root), whoever starts it.", lesson: "os-protection-security" },
  { term: "ACL", aliases: ["access control list"], def: "A list stored with an object saying which users or groups may do what to it.", lesson: "os-protection-security" },
  { term: "seccomp", def: "A Linux filter limiting which system calls a process may make; containers use it to block risky ones.", lesson: "os-protection-security" },
  { term: "least privilege", aliases: ["principle of least privilege"], def: "Giving each program only the rights it needs, for only as long as it needs them.", lesson: "os-protection-security" },
  // ── Networks: foundations and the link layer ──
  { term: "packet switching", def: "Sending data as independent packets that share links with everyone else's, each routed on its own, instead of reserving a path in advance.", lesson: "cn-how-data-travels" },
  { term: "circuit switching", def: "Reserving a dedicated path and bandwidth for the whole conversation before any data flows, as the old telephone network did.", lesson: "cn-how-data-travels" },
  { term: "store-and-forward", def: "A device receives a whole packet or frame, checks it, and only then sends it on, so each hop adds one transmission time.", lesson: "cn-how-data-travels", exclude: ["cn-email-file-transfer"] },
  { term: "propagation delay", def: "The time a signal needs to travel the distance of a link: about 5 µs per kilometre of fibre.", lesson: "cn-latency-bandwidth" },
  { term: "transmission delay", aliases: ["serialization delay"], def: "The time to push all of a packet's bits onto a link: packet size divided by link rate.", lesson: "cn-latency-bandwidth" },
  { term: "RTT", aliases: ["round-trip time", "round trip time"], def: "Round-trip time: how long a message takes to reach the other side and for the reply to come back.", lesson: "cn-latency-bandwidth" },
  { term: "bandwidth-delay product", aliases: ["BDP"], def: "Bandwidth × round-trip time: how many bytes must be in flight at once to keep a path fully busy.", lesson: "cn-latency-bandwidth" },
  { term: "MAC address", def: "The 48-bit hardware address of a network interface, used to deliver frames on one local link.", lesson: "cn-ethernet-switching" },
  { term: "frame", def: "The unit of data on a single link (Ethernet, Wi-Fi), with source and destination MAC addresses and a CRC.", lesson: "cn-ethernet-switching", only: ["cn-how-data-travels", "cn-layered-models", "cn-encapsulation", "cn-error-detection", "cn-arq-protocols", "cn-mac-protocols", "cn-arp-dhcp", "cn-routing"] },
  { term: "VLAN", def: "A virtual LAN: one physical switch network split into separate broadcast domains by tagging each frame with a network ID.", lesson: "cn-ethernet-switching" },
  { term: "broadcast domain", def: "The set of devices that receive each other's broadcast frames; routers (and VLANs) are its boundaries.", lesson: "cn-ethernet-switching" },
  { term: "collision domain", def: "The devices that share one medium so that their transmissions can collide; every switch port is its own.", lesson: "cn-ethernet-switching" },
  { term: "encapsulation", def: "Each layer wrapping the data from the layer above in its own header (and sometimes trailer) on the way down the stack.", lesson: "cn-encapsulation" },
  { term: "MTU", def: "Maximum transmission unit: the largest packet a link can carry, 1,500 bytes on standard Ethernet.", lesson: "cn-mtu-congestion" },
  { term: "MSS", def: "Maximum segment size: the largest TCP payload in one segment, the MTU minus the IP and TCP headers (1,460 bytes on IPv4 Ethernet).", lesson: "cn-encapsulation" },
  { term: "CRC", def: "Cyclic redundancy check: a remainder from polynomial division sent with each frame, so the receiver can detect corrupted bits.", lesson: "cn-error-detection" },
  { term: "parity bit", def: "One extra bit that makes the number of 1s even (or odd); it detects any odd number of flipped bits.", lesson: "cn-error-detection" },
  { term: "Hamming distance", def: "The number of bit positions in which two codewords differ; it decides how many errors a code can detect or correct.", lesson: "cn-error-detection" },
  { term: "ARQ", def: "Automatic repeat request: the receiver acknowledges what arrived and the sender resends what wasn't acknowledged in time.", lesson: "cn-arq-protocols" },
  { term: "Go-Back-N", def: "A sliding-window protocol whose receiver accepts only in-order frames, so after a loss the sender resends that frame and everything after it.", lesson: "cn-arq-protocols" },
  { term: "Selective Repeat", def: "A sliding-window protocol whose receiver buffers out-of-order frames, so only lost frames are resent.", lesson: "cn-arq-protocols" },
  { term: "CSMA/CD", def: "Classic Ethernet's rule: listen before sending, stop when a collision is detected, and wait a random, growing time before retrying.", lesson: "cn-mac-protocols" },
  { term: "CSMA/CA", def: "Wi-Fi's rule: listen, wait a random backoff before sending, and confirm every frame with an ACK, since collisions can't be detected.", lesson: "cn-mac-protocols" },
  { term: "hidden terminal", def: "Two stations that both reach an access point but can't hear each other, so their transmissions collide at the access point.", lesson: "cn-mac-protocols" },
  { term: "ARP", def: "Address Resolution Protocol: asks the local network which MAC address belongs to an IP address.", lesson: "cn-arp-dhcp" },
  { term: "DHCP", def: "The protocol that gives a joining device its IP address, mask, default gateway and DNS servers, for a limited lease.", lesson: "cn-arp-dhcp" },
  // ── Networks: IP and routing ──
  { term: "CIDR", def: "Classless addressing: a prefix length (/24) says how many leading bits name the network, replacing the old fixed classes.", lesson: "cn-ipv4-addressing" },
  { term: "subnet mask", def: "A mask with 1s for the network bits of an address (255.255.255.0 = /24); AND it with an address to get the network.", lesson: "cn-ipv4-addressing" },
  { term: "private address", aliases: ["private IP"], def: "An address from 10/8, 172.16/12 or 192.168/16: usable inside any network but never routed on the public internet.", lesson: "cn-ipv4-addressing" },
  { term: "default gateway", def: "The router a host sends packets to when the destination isn't on its own subnet.", lesson: "cn-routing" },
  { term: "longest-prefix match", aliases: ["longest prefix match"], def: "The routing rule that the most specific matching route wins when several prefixes contain the destination.", lesson: "cn-routing" },
  { term: "ECMP", def: "Equal-cost multipath: spreading flows across several equally good paths, hashing each flow so its packets stay on one path.", lesson: "cn-routing" },
  { term: "TTL", def: "Time to live: a hop counter in each IP packet, decremented by every router; the packet is dropped when it reaches 0.", lesson: "cn-ip-packet-icmp", exclude: ["cn-dns-", "cn-cdn", "cn-http-caching", "cn-java-networking", "cn-cookies-sessions"] },
  { term: "ICMP", def: "The internet's control and error messages: echo for ping, time exceeded for traceroute, destination unreachable, fragmentation needed.", lesson: "cn-ip-packet-icmp" },
  { term: "NAT", def: "Network address translation: a router rewriting private source addresses and ports to its public address, and back for replies.", lesson: "cn-nat" },
  { term: "conntrack", def: "Linux's table of tracked connections, used by NAT and stateful firewalls to recognize replies; it can fill up under load.", lesson: "cn-nat" },
  { term: "SLAAC", def: "IPv6 stateless autoconfiguration: a host builds its own address from the router-advertised prefix plus an interface ID.", lesson: "cn-ipv6" },
  { term: "Dijkstra's algorithm", aliases: ["Dijkstra"], def: "A shortest-path algorithm that repeatedly settles the closest unsettled node; link-state routers run it on their map of the network.", lesson: "cn-routing-algorithms" },
  { term: "distance vector", def: "Routing in which each router shares its distance table with its neighbours and takes the best neighbour's distance plus the link cost.", lesson: "cn-routing-algorithms" },
  { term: "link state", aliases: ["link-state"], def: "Routing in which every router floods a description of its links, builds the same map, and computes shortest paths itself.", lesson: "cn-routing-algorithms" },
  { term: "count to infinity", def: "A distance-vector failure where routers keep raising each other's stale distances after a link fails, looping packets meanwhile.", lesson: "cn-routing-algorithms" },
  { term: "OSPF", def: "A link-state routing protocol used inside organizations; routers flood link states and run Dijkstra.", lesson: "cn-routing-algorithms" },
  { term: "RIP", def: "An old distance-vector routing protocol that counts hops, up to 15 (16 means unreachable).", lesson: "cn-routing-algorithms" },
  { term: "BGP", def: "Border Gateway Protocol: how independent networks (autonomous systems) announce which address ranges they can reach.", lesson: "cn-bgp-anycast" },
  { term: "autonomous system", def: "A network under one administration with its own routing policy and AS number, such as an ISP or a cloud provider.", lesson: "cn-bgp-anycast" },
  { term: "anycast", def: "Announcing the same IP address from many locations, so each user is routed to the nearest one.", lesson: "cn-bgp-anycast" },
  // ── Networks: transport ──
  { term: "socket", def: "The program's handle on one network endpoint: an address, a port and the kernel's buffers and connection state.", lesson: "cn-sockets" },
  { term: "ephemeral port", def: "A temporary local port the operating system picks for an outgoing connection.", lesson: "cn-sockets" },
  { term: "three-way handshake", def: "TCP's connection setup: SYN, SYN-ACK, ACK, which agrees on starting sequence numbers and costs one round trip.", lesson: "cn-tcp-handshake" },
  { term: "SYN flood", def: "An attack sending many connection requests that never complete, to fill the server's table of half-open connections.", lesson: "cn-tcp-handshake" },
  { term: "sequence number", def: "TCP's count of bytes sent, so the receiver can put data in order, drop duplicates and acknowledge exactly what arrived.", lesson: "cn-tcp-fundamentals", exclude: ["cn-routing-algorithms", "cn-crypto-foundations", "cn-tls-handshake"] },
  { term: "retransmission timeout", aliases: ["RTO"], def: "How long TCP waits for an acknowledgement before resending, computed from measured round-trip times.", lesson: "cn-tcp-reliability" },
  { term: "fast retransmit", def: "TCP resending a segment after three duplicate ACKs, without waiting for the retransmission timeout.", lesson: "cn-tcp-reliability" },
  { term: "SACK", def: "Selective acknowledgement: a TCP option telling the sender exactly which ranges arrived, so it resends only the gaps.", lesson: "cn-tcp-reliability" },
  { term: "head-of-line blocking", def: "When one lost or slow item holds up everything queued behind it, even items that are ready.", lesson: "cn-tcp-reliability" },
  { term: "flow control", def: "The receiver telling the sender how much more data it can accept, so a fast sender can't overflow a slow receiver.", lesson: "cn-tcp-flow-control" },
  { term: "receive window", aliases: ["rwnd"], def: "The free space in the receiver's buffer, advertised in every ACK; the sender may not have more unacknowledged data in flight.", lesson: "cn-tcp-flow-control" },
  { term: "window scaling", def: "A TCP option multiplying the 16-bit window field by a power of two, so windows can exceed 64 KB.", lesson: "cn-tcp-flow-control" },
  { term: "Nagle's algorithm", def: "TCP holding back small writes until earlier data is acknowledged; disabled with TCP_NODELAY for latency-sensitive traffic.", lesson: "cn-tcp-flow-control" },
  { term: "congestion window", aliases: ["cwnd"], def: "The sender's own limit on data in flight, grown while the network delivers and cut when it shows congestion.", lesson: "cn-tcp-congestion-control" },
  { term: "slow start", def: "TCP's start-up phase: the congestion window doubles every round trip until loss or a threshold.", lesson: "cn-tcp-congestion-control" },
  { term: "AIMD", def: "Additive increase, multiplicative decrease: grow slowly, halve on loss; it makes competing flows converge on fair shares.", lesson: "cn-tcp-congestion-control" },
  { term: "bufferbloat", def: "Oversized router buffers that fill up before any loss occurs, adding long queueing delays.", lesson: "cn-tcp-congestion-control" },
  { term: "ECN", def: "Explicit Congestion Notification: routers mark packets instead of dropping them, so senders slow down without losing data.", lesson: "cn-tcp-congestion-control" },
  { term: "TIME_WAIT", def: "The state the side that closed first keeps for about a minute, so delayed old packets can't confuse a new connection.", lesson: "cn-tcp-termination" },
  { term: "CLOSE_WAIT", def: "The peer has closed its side, but this application hasn't closed its socket yet; many of them mean a leak.", lesson: "cn-tcp-termination" },
  { term: "datagram", def: "A self-contained message sent on its own (as with UDP), with no connection and no delivery guarantee.", lesson: "cn-udp" },
  // ── Networks: DNS ──
  { term: "recursive resolver", def: "The DNS server that does the lookup work for clients, asking root, TLD and authoritative servers and caching answers.", lesson: "cn-dns-fundamentals" },
  { term: "authoritative server", aliases: ["authoritative name server"], def: "A DNS server holding the actual records for a zone; its answers are the source of truth.", lesson: "cn-dns-fundamentals", exclude: ["cn-cdn"] },
  { term: "DNSSEC", def: "Signatures on DNS records, verified along a chain of keys from the root, so forged answers can be detected.", lesson: "cn-dns-fundamentals" },
  { term: "CNAME", def: "A DNS record saying \"this name is an alias for that other name; look that one up instead\".", lesson: "cn-dns-records" },
  { term: "MX record", def: "A DNS record naming the mail servers that accept email for a domain, with preference numbers.", lesson: "cn-dns-records" },
  { term: "PTR record", def: "A reverse-DNS record mapping an IP address back to a name.", lesson: "cn-dns-records" },
  // ── Networks: HTTP ──
  { term: "idempotent", def: "Doing it twice has the same effect as doing it once, so it is safe to retry.", lesson: "cn-http-fundamentals" },
  { term: "persistent connection", aliases: ["HTTP keep-alive"], def: "Reusing one TCP (and TLS) connection for many HTTP requests instead of opening one per request.", lesson: "cn-http-connections", exclude: ["cn-realtime"] },
  { term: "chunked encoding", aliases: ["chunked transfer encoding"], def: "Sending an HTTP/1.1 body as size-prefixed pieces, so its total length needn't be known in advance.", lesson: "cn-http-connections" },
  { term: "connection pool", def: "A set of open connections kept for reuse, so each request avoids new TCP and TLS handshakes.", lesson: "cn-http-connections" },
  { term: "request smuggling", def: "An attack exploiting a proxy and a server that disagree about where a request ends, hiding a second request inside the first.", lesson: "cn-http-connections" },
  { term: "ETag", def: "A version tag the server attaches to a response, so caches can ask \"has it changed?\" and get a cheap 304 if not.", lesson: "cn-http-caching" },
  { term: "conditional request", def: "A request carrying a validator (If-None-Match, If-Match) so the server can answer \"not modified\" or refuse a conflicting update.", lesson: "cn-http-caching" },
  { term: "multiplexing", def: "Carrying many independent requests and responses interleaved on one connection, as HTTP/2 does with streams.", lesson: "cn-http2" },
  { term: "HPACK", def: "HTTP/2's header compression: repeated headers become small indexes into tables both sides keep.", lesson: "cn-http2" },
  { term: "QUIC", def: "A transport protocol over UDP with TLS 1.3 built in and independent streams; HTTP/3 runs on it.", lesson: "cn-http3-quic" },
  { term: "0-RTT", def: "Sending application data in the very first flight to a server visited before; fast, but an attacker can replay it.", lesson: "cn-http3-quic" },
  // ── Networks: security ──
  { term: "symmetric encryption", def: "Encryption where both sides use the same secret key; fast, but the key must be shared securely first.", lesson: "cn-crypto-foundations" },
  { term: "public-key cryptography", aliases: ["asymmetric encryption", "asymmetric cryptography"], def: "Cryptography with a key pair: a public key anyone may have and a private key only the owner holds.", lesson: "cn-crypto-foundations" },
  { term: "Diffie–Hellman", aliases: ["Diffie-Hellman"], def: "A method for two parties to agree on a shared secret over a public channel without ever sending the secret.", lesson: "cn-crypto-foundations" },
  { term: "forward secrecy", def: "Recorded traffic stays safe even if the server's long-term key leaks later, because each session used fresh keys.", lesson: "cn-crypto-foundations" },
  { term: "message authentication code", aliases: ["HMAC"], def: "A tag computed from a message and a secret key; only key holders can produce it, so it proves the message is unaltered.", lesson: "cn-crypto-foundations" },
  { term: "AEAD", def: "Authenticated encryption: one operation that encrypts data and detects any tampering (AES-GCM, ChaCha20-Poly1305).", lesson: "cn-crypto-foundations" },
  { term: "digital signature", def: "A value only the private key's holder can create and anyone with the public key can check, proving who produced the data.", lesson: "cn-crypto-foundations" },
  { term: "certificate authority", def: "An organization that vouches for which public key belongs to which domain by signing certificates.", lesson: "cn-certificates-pki" },
  { term: "intermediate certificate", aliases: ["intermediate CA"], def: "A CA certificate between the root and a site's certificate; servers must send it so clients can complete the chain.", lesson: "cn-certificates-pki" },
  { term: "OCSP", def: "Online Certificate Status Protocol: asking whether a certificate has been revoked; stapling lets the server deliver the answer.", lesson: "cn-certificates-pki" },
  { term: "mTLS", aliases: ["mutual TLS"], def: "TLS in which the client also presents a certificate, so both sides prove their identity.", lesson: "cn-certificates-pki" },
  { term: "SNI", def: "Server Name Indication: the hostname a client sends in its first TLS message, so one IP can serve many sites' certificates.", lesson: "cn-tls-handshake" },
  { term: "ALPN", def: "A TLS extension in which client and server agree on the application protocol (h2, http/1.1) during the handshake.", lesson: "cn-tls-handshake" },
  { term: "HSTS", def: "A header telling browsers to use only HTTPS for a site from now on, defeating downgrade-to-HTTP attacks.", lesson: "cn-tls-handshake" },
  // ── Networks: web ──
  { term: "same-origin policy", def: "The browser rule that a page's scripts may read responses only from the same scheme, host and port.", lesson: "cn-cors-csrf" },
  { term: "CORS", def: "Cross-origin resource sharing: response headers with which a server lets pages from other origins read its responses.", lesson: "cn-cors-csrf" },
  { term: "preflight request", aliases: ["preflight"], def: "An OPTIONS request a browser sends first to ask whether a cross-origin request with this method and these headers is allowed.", lesson: "cn-cors-csrf" },
  { term: "CSRF", def: "Cross-site request forgery: another site making the user's browser send an authenticated request the user never intended.", lesson: "cn-cors-csrf" },
  { term: "JWT", def: "JSON Web Token: signed claims (who you are, until when) that services can verify without a lookup.", lesson: "cn-cookies-sessions" },
  { term: "WebSocket", def: "A persistent, two-way message channel opened by upgrading an HTTP connection.", lesson: "cn-realtime" },
  { term: "server-sent events", aliases: ["SSE"], def: "A long-lived HTTP response through which a server pushes text events to the browser, with automatic reconnect.", lesson: "cn-realtime" },
  { term: "long polling", def: "The client asks for updates and the server holds the request open until there is news, then the client asks again.", lesson: "cn-realtime" },
  { term: "reverse proxy", def: "A server in front of your servers that receives clients' requests and forwards them, often adding TLS, caching or routing.", lesson: "cn-proxies-load-balancers" },
  { term: "health check", def: "A probe a load balancer sends to each backend to decide whether to keep sending it traffic.", lesson: "cn-proxies-load-balancers" },
  { term: "connection draining", def: "Stopping new requests to an instance while letting its in-flight requests finish, before shutting it down.", lesson: "cn-proxies-load-balancers" },
  { term: "CDN", def: "Content delivery network: caches and proxies in many cities serving content close to users.", lesson: "cn-cdn" },
  { term: "PoP", aliases: ["point of presence"], def: "One of a CDN's or network's locations, where users connect and content is cached.", lesson: "cn-cdn" },
  { term: "gRPC", def: "A remote-procedure-call framework sending protobuf messages over HTTP/2, with code generated from a service definition.", lesson: "cn-api-styles" },
  { term: "GraphQL", def: "An API style where the client sends a query naming exactly the fields it wants, and gets them in one response.", lesson: "cn-api-styles" },
  { term: "webhook", def: "An HTTP request a service sends to your URL to notify you of an event.", lesson: "cn-api-styles" },
  // ── Networks: performance and infrastructure ──
  { term: "tail latency", def: "The latency of the slowest requests, such as the 99th percentile, which often decides user experience.", lesson: "cn-tail-latency" },
  { term: "hedged request", def: "Sending a second copy of a slow request to another replica and using whichever answer arrives first.", lesson: "cn-tail-latency" },
  { term: "MSS clamping", def: "A router lowering the MSS in passing TCP handshakes so segments fit a smaller tunnel MTU.", lesson: "cn-mtu-congestion" },
  { term: "service mesh", def: "A layer of proxies beside every service that handles service-to-service traffic: mTLS, retries, timeouts, routing and metrics.", lesson: "cn-service-networking" },
  { term: "sidecar", def: "A helper container running next to the application in the same pod, such as a mesh proxy.", lesson: "cn-service-networking" },
  { term: "circuit breaker", def: "A guard that stops calling a failing dependency for a while, failing fast instead of waiting, then probes before resuming.", lesson: "cn-service-networking" },
  { term: "service discovery", def: "How a client finds the current network addresses of the instances of a service.", lesson: "cn-service-networking" },
  { term: "network namespace", def: "A private copy of the Linux network stack (interfaces, routes, firewall rules) used to isolate containers.", lesson: "cn-container-networking" },
  { term: "veth pair", def: "Two linked virtual network interfaces, like a cable: one end inside a container, the other on the host.", lesson: "cn-container-networking" },
  { term: "overlay network", def: "A virtual network whose packets are wrapped inside other packets (VXLAN, for example) to cross the real network.", lesson: "cn-container-networking" },
  { term: "ClusterIP", def: "A Kubernetes Service's virtual IP address, translated to a ready pod's address on every node.", lesson: "cn-container-networking" },
  { term: "VPN", def: "Virtual private network: an encrypted tunnel that makes a remote device or site appear to be on a private network.", lesson: "cn-vpn-nat-traversal" },
  { term: "IPsec", def: "A suite of protocols encrypting and authenticating IP packets, used for site-to-site VPNs.", lesson: "cn-vpn-nat-traversal" },
  { term: "STUN", def: "A protocol that tells a device behind NAT what public address and port the outside world sees for it.", lesson: "cn-vpn-nat-traversal" },
  { term: "TURN", def: "A relay server that forwards traffic between two peers when they can't connect directly.", lesson: "cn-vpn-nat-traversal" },
  { term: "hole punching", def: "Two peers behind NATs both sending first, so each NAT opens a mapping and their packets can flow directly.", lesson: "cn-vpn-nat-traversal" },
  { term: "stateful firewall", def: "A firewall that tracks connections and admits replies to allowed outgoing connections, while dropping unsolicited inbound traffic.", lesson: "cn-network-security" },
  { term: "DMZ", def: "A separate network zone for internet-facing servers, with firewalls between it, the internet and the internal network.", lesson: "cn-network-security" },
  { term: "WAF", def: "Web application firewall: inspects HTTP requests for attacks such as SQL injection, and rate-limits abusive clients.", lesson: "cn-network-security" },
  { term: "DDoS", def: "Distributed denial of service: many sources flooding a target's bandwidth, connection state or application capacity.", lesson: "cn-network-security" },
  { term: "token bucket", def: "A rate limiter: tokens refill at a fixed rate up to a cap, and each request spends one, allowing short bursts.", lesson: "cn-network-security" },
  { term: "zero trust", def: "Granting access per request based on verified identity, never because a request comes from inside the network.", lesson: "cn-network-security" },
  // ── Networks: application protocols and Java ──
  { term: "SMTP", def: "The protocol that sends email: from a mail app to its server, and between mail servers.", lesson: "cn-email-file-transfer" },
  { term: "IMAP", def: "A protocol for reading email that stays on the server, synchronized across devices.", lesson: "cn-email-file-transfer" },
  { term: "SPF", def: "A DNS record listing which servers may send email for a domain.", lesson: "cn-email-file-transfer" },
  { term: "DKIM", def: "Email signing: the sending domain signs headers and body, and publishes the public key in DNS.", lesson: "cn-email-file-transfer" },
  { term: "DMARC", def: "A DNS policy requiring SPF or DKIM to pass for the domain in the visible From address, and saying what to do if not.", lesson: "cn-email-file-transfer" },
  { term: "SFTP", def: "File transfer over an SSH connection: one encrypted connection, unlike FTP's two clear-text ones.", lesson: "cn-email-file-transfer" },
  { term: "truststore", def: "The set of CA certificates a Java process trusts when checking servers' certificates; by default the JDK's cacerts file.", lesson: "cn-java-networking" },
];
